    <ul class="schemes" data-group data-items=".scheme" data-cpull="0" :aria-label="t('Схемы ссылок reclash://', 'reclash:// link schemes')">
      <li class="scheme" data-mg><code>reclash://connect</code><span>{{ t("Запустить туннель и подключиться", "Start the tunnel and connect") }}</span><button class="cp" type="button" data-copy="reclash://connect" :aria-label="t('Скопировать reclash://connect', 'Copy reclash://connect')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://disconnect</code><span>{{ t("Остановить туннель", "Stop the tunnel") }}</span><button class="cp" type="button" data-copy="reclash://disconnect" :aria-label="t('Скопировать reclash://disconnect', 'Copy reclash://disconnect')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://toggle</code><span>{{ t("Подключить, если остановлено, иначе отключить", "Connect if stopped, otherwise disconnect") }}</span><button class="cp" type="button" data-copy="reclash://toggle" :aria-label="t('Скопировать reclash://toggle', 'Copy reclash://toggle')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://open</code><span>{{ t("Вывести окно на передний план", "Bring the window to the front") }}</span><button class="cp" type="button" data-copy="reclash://open" :aria-label="t('Скопировать reclash://open', 'Copy reclash://open')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://close</code><span>{{ t("Свернуть в трей или выйти, если так настроено", "Minimize to the tray or exit if configured") }}</span><button class="cp" type="button" data-copy="reclash://close" :aria-label="t('Скопировать reclash://close', 'Copy reclash://close')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://add/&lt;url&gt;</code><span>{{ t("URL подписки — добавляется после подтверждения", "Subscription URL: added after confirmation") }}</span><button class="cp" type="button" data-copy="reclash://add/&lt;url&gt;" :aria-label="t('Скопировать reclash://add/<url>', 'Copy reclash://add/<url>')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://import/&lt;base64&gt;</code><span>{{ t("Конфиг в base64 — импортируется как профиль", "Base64 config: imported as a profile") }}</span><button class="cp" type="button" data-copy="reclash://import/&lt;base64&gt;" :aria-label="t('Скопировать reclash://import/<base64>', 'Copy reclash://import/<base64>')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
      <li class="scheme" data-mg><code>reclash://install-config?url=&lt;url&gt;</code><span>{{ t("Совместимая ссылка кнопок Clash и FlClash; необязательный &name= задаёт имя профиля", "Compatible with Clash and FlClash buttons; optional &name= sets the profile name") }}</span><button class="cp" type="button" data-copy="reclash://install-config?url=&lt;url&gt;" :aria-label="t('Скопировать reclash://install-config?url=<url>', 'Copy reclash://install-config?url=<url>')"><svg viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg></button></li>
    </ul>
    <p class="note warn" style="margin-top:20px"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 3 18 17H2Z M10 8v4m0 2.5v.1" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" stroke-linecap="round"/></svg>{{ t("Ссылки add, import и install-config несут доступ к вашему трафику. Открывайте только те, которым доверяете.", "The add, import and install-config links carry access to your traffic. Only open links you trust.") }}</p>
